argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$files=@(
'app/scripts/operator-lifecycle-r40.ps1',
'app/scripts/pause-all-r40.cmd',
'app/scripts/pause-browser-r40.cmd',
'app/scripts/resume-attach-r40.cmd',
'app/scripts/resume-managed-r40.cmd'
);
$out=@();
foreach($f in $files){
  $diff=@(& $git -C $repo diff -- $f);
  $out += [pscustomobject]@{file=$f;diff=($diff -join [Environment]::NewLine)}
}
$out|ConvertTo-Json -Depth 4 -Compress
